import { useEffect, useMemo, useState } from 'react'
import { apiFetch } from '../../../lib/api'
import { downloadExcel } from '../../../lib/exportExcel'
import { AlertCircle, Check, ChevronDown, Edit2, Eye, FileSpreadsheet, Loader2, Plus, RefreshCw, Search, Trash2, X } from 'lucide-react'

const today = () => new Date().toISOString().slice(0, 10)
const text = value => value == null ? '' : String(value)
const num = value => Number(value || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })

function Notice({ message, type = 'success', onClose }) {
  if (!message) return null
  return <div className={`fixed bottom-5 left-1/2 z-[100] flex max-w-[92vw] -translate-x-1/2 items-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold text-white shadow-2xl ${type === 'error' ? 'bg-rose-600' : 'bg-emerald-600'}`}><span>{type === 'error' ? <AlertCircle className="h-4 w-4" /> : <Check className="h-4 w-4" />}</span><span>{message}</span><button onClick={onClose}><X className="h-4 w-4 opacity-80" /></button></div>
}

function Busy({ show }) {
  if (!show) return null
  return <div className="fixed inset-0 z-[90] flex items-center justify-center bg-slate-950/20 backdrop-blur-[2px]"><div className="flex items-center gap-3 rounded-2xl bg-white px-5 py-4 text-sm font-semibold text-slate-700 shadow-2xl dark:bg-[#1a1f35] dark:text-slate-100"><Loader2 className="h-5 w-5 animate-spin text-indigo-500" /> Loading…</div></div>
}

function Select({ value, onChange, children, placeholder = '-- Select --', disabled = false }) {
  return <div className="relative"><select value={value || ''} onChange={onChange} disabled={disabled} className="w-full appearance-none rounded-lg border border-slate-200 bg-white px-3 py-2 pr-8 text-sm text-slate-700 outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:cursor-not-allowed disabled:opacity-50 dark:border-indigo-500/25 dark:bg-[#1e2238] dark:text-slate-100 dark:focus:ring-indigo-500/20"><option value="">{placeholder}</option>{children}</select><ChevronDown className="pointer-events-none absolute right-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /></div>
}

function Field({ label, children, required = false }) {
  return <label className="flex min-w-0 flex-col gap-1.5"><span className="text-[11px] font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400">{label}{required && <em className="ml-1 not-italic text-rose-500">*</em>}</span>{children}</label>
}

function Input({ value, onChange, type = 'text', placeholder = '', disabled = false }) {
  return <input value={value ?? ''} onChange={onChange} type={type} placeholder={placeholder} disabled={disabled} className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 outline-none placeholder:text-slate-400 focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:opacity-50 dark:border-indigo-500/25 dark:bg-[#1e2238] dark:text-slate-100 dark:focus:ring-indigo-500/20" />
}

function PageFrame({ title, subtitle, children, busy, notice, setNotice }) {
  return <div className="mx-auto w-full max-w-[1500px] space-y-4 pb-8"><Busy show={busy} /><Notice message={notice?.message} type={notice?.type} onClose={() => setNotice(null)} /><div><h1 className="text-xl font-bold text-slate-800 dark:text-slate-100">{title}</h1>{subtitle && <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">{subtitle}</p>}</div>{children}</div>
}

function ActionButton({ children, onClick, tone = 'primary', disabled = false }) {
  const colors = { primary: 'bg-indigo-600 hover:bg-indigo-700', success: 'bg-emerald-600 hover:bg-emerald-700', danger: 'bg-rose-600 hover:bg-rose-700', neutral: 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-200 dark:hover:bg-slate-700' }
  return <button type="button" onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-lg px-4 py-2 text-sm font-semibold text-white shadow-sm transition disabled:cursor-not-allowed disabled:opacity-60 ${colors[tone]}`}>{children}</button>
}

function SearchBar({ value, onChange }) {
  return <div className="relative min-w-0 flex-1"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={value} onChange={e => onChange(e.target.value)} placeholder="Search…" /><span className="pointer-events-none absolute inset-y-0 left-9" /></div>
}

function DataTable({ rows, columns, search = '', empty = 'No Record Found.', mobileCard = true }) {
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase(); if (!q) return rows || []
    return (rows || []).filter(row => columns.some(col => text(typeof col.value === 'function' ? col.value(row) : row[col.key]).toLowerCase().includes(q)))
  }, [rows, columns, search])
  return <>{mobileCard && <div className="space-y-2 md:hidden">{filtered.map((row, i) => <div key={row.id ?? row.registrationNo ?? `${i}`} className="rounded-xl border border-slate-200 bg-white p-3 shadow-sm dark:border-indigo-500/15 dark:bg-[#1a1f35]"><div className="mb-2 flex items-center justify-between text-xs text-slate-400"><span>#{i + 1}</span><span className="flex gap-2">{columns.slice(-2).map((col, j) => <span key={j}>{col.render ? col.render(row) : text(typeof col.value === 'function' ? col.value(row) : row[col.key])}</span>)}</span></div>{columns.slice(0, -2).map((col, j) => <div key={j} className="flex justify-between gap-3 border-t border-slate-100 py-1.5 text-sm dark:border-white/5"><span className="text-slate-500 dark:text-slate-400">{col.label}</span><span className="text-right font-medium text-slate-700 dark:text-slate-200">{col.render ? col.render(row) : text(typeof col.value === 'function' ? col.value(row) : row[col.key])}</span></div>)}</div>)}{!filtered.length && <Empty text={empty} />}</div>}<div className="hidden overflow-x-auto md:block"><table className="min-w-full text-left text-sm"><thead><tr className="border-b border-slate-200 bg-slate-50 dark:border-indigo-500/15 dark:bg-white/[.03]">{columns.map((col, i) => <th key={i} className="whitespace-nowrap px-3 py-3 text-[11px] font-bold uppercase tracking-wide text-slate-500 dark:text-slate-400">{col.label}</th>)}</tr></thead><tbody>{filtered.map((row, i) => <tr key={row.id ?? row.registrationNo ?? `${i}`} className="border-b border-slate-100 hover:bg-slate-50 dark:border-white/5 dark:hover:bg-white/[.025]">{columns.map((col, j) => <td key={j} className="px-3 py-3 text-slate-700 dark:text-slate-200">{col.render ? col.render(row) : text(typeof col.value === 'function' ? col.value(row) : row[col.key])}</td>)}</tr>)}</tbody></table>{!filtered.length && <Empty text={empty} />}</div></>
}

function Empty({ text: label }) { return <div className="rounded-xl border border-dashed border-slate-200 bg-white px-4 py-10 text-center text-sm text-slate-400 dark:border-indigo-500/15 dark:bg-[#1a1f35]">{label}</div> }
function Card({ children, className = '' }) { return <section className={`rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-indigo-500/15 dark:bg-[#1a1f35] ${className}`}>{children}</section> }
function CardHead({ children, right }) { return <div className="flex flex-col gap-3 border-b border-slate-100 px-4 py-3 sm:flex-row sm:items-center sm:justify-between dark:border-white/5"><h2 className="text-sm font-bold text-slate-700 dark:text-slate-200">{children}</h2>{right}</div> }

function useNotice() { const [notice, setNotice] = useState(null); const show = (message, type = 'success') => setNotice({ message, type }); return [notice, setNotice, show] }
function useSave(action, show, setBusy) { return async (...args) => { setBusy(true); try { const result = await action(...args); show(result?.message || 'Record saved successfully'); return result } catch (e) { show(e.message, 'error'); throw e } finally { setBusy(false) } } }

function GroupMaster({ boot }) {
  const [rows, setRows] = useState(boot.expenseGroups || []); const [name, setName] = useState(''); const [edit, setEdit] = useState(null); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice] = useNotice()
  useEffect(() => setRows(boot.expenseGroups || []), [boot.expenseGroups])
  const save = async () => { if (!name.trim()) return setNotice({ message: 'Group name is required', type: 'error' }); setBusy(true); try { await apiFetch(edit ? `/canteen/expense-groups/${edit.id}` : '/canteen/expense-groups', { method: edit ? 'PUT' : 'POST', body: JSON.stringify({ groupName: name.trim() }) }); setRows(await apiFetch('/canteen/expense-groups')); setName(''); setEdit(null); setNotice({ message: edit ? 'Record updated successfully' : 'Record saved successfully' }) } catch (e) { setNotice({ message: e.message, type: 'error' }) } finally { setBusy(false) } }
  const remove = async row => { if (!window.confirm(`Delete ${row.group_name || row.groupName}?`)) return; setBusy(true); try { await apiFetch(`/canteen/expense-groups/${row.id}`, { method: 'DELETE' }); setRows(await apiFetch('/canteen/expense-groups')); setNotice({ message: 'Record deleted successfully' }) } catch (e) { setNotice({ message: e.message, type: 'error' }) } finally { setBusy(false) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Group Name', value: r => r.group_name || r.groupName }, { label: 'Actions', render: r => <span className="flex gap-2"><button className="text-indigo-600" onClick={() => { setEdit(r); setName(r.group_name || r.groupName) }}><Edit2 className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => remove(r)}><Trash2 className="h-4 w-4" /></button></span> }]
  return <PageFrame title="Expense Group" subtitle="Define and maintain Canteen expense groups." busy={busy} notice={notice} setNotice={setNotice}><Card><CardHead right={<div className="flex flex-wrap gap-2"><SearchBar value={search} onChange={setSearch} /><ActionButton tone="neutral" onClick={() => downloadExcel('Expense_Group.xls', rows, [{ key: 'group_name', label: 'Group Name' }])}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton></div>}>{edit ? 'Update Expense Group' : 'Add Expense Group'}</CardHead><div className="grid gap-3 p-4 sm:grid-cols-[1fr_auto_auto]"><Field label="Group Name" required><Input value={name} onChange={e => setName(e.target.value)} onKeyDown={e => e.key === 'Enter' && save()} /></Field><ActionButton onClick={save}>{edit ? <><Check className="h-4 w-4" /> Update</> : <><Plus className="h-4 w-4" /> Add</>}</ActionButton>{edit && <ActionButton tone="neutral" onClick={() => { setEdit(null); setName('') }}><X className="h-4 w-4" /> Cancel</ActionButton>}</div></Card><Card><CardHead>Expense Groups</CardHead><DataTable rows={rows} columns={columns} search={search} /></Card></PageFrame>
}

function ExpenseNameMaster({ boot }) {
  const [groups, setGroups] = useState(boot.expenseGroups || []); const [rows, setRows] = useState(boot.expenseNames || []); const [form, setForm] = useState({ groupId: '', expenseName: '' }); const [edit, setEdit] = useState(null); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  useEffect(() => { setGroups(boot.expenseGroups || []); setRows(boot.expenseNames || []) }, [boot.expenseGroups, boot.expenseNames])
  const reload = async () => { const [g, n] = await Promise.all([apiFetch('/canteen/expense-groups'), apiFetch('/canteen/expense-names')]); setGroups(g); setRows(n) }
  const save = async () => { if (!form.groupId || !form.expenseName.trim()) return show('Group and expense name are required', 'error'); setBusy(true); try { await apiFetch(edit ? `/canteen/expense-names/${edit.id}` : '/canteen/expense-names', { method: edit ? 'PUT' : 'POST', body: JSON.stringify(form) }); await reload(); setForm({ groupId: '', expenseName: '' }); setEdit(null); show(edit ? 'Record updated successfully' : 'Record saved successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const remove = async row => { if (!window.confirm(`Delete ${row.expenseName || row.expense_name}?`)) return; setBusy(true); try { await apiFetch(`/canteen/expense-names/${row.id}`, { method: 'DELETE' }); await reload(); show('Record deleted successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Expense Name', value: r => r.expenseName || r.expense_name }, { label: 'Group', value: r => r.groupName || '' }, { label: 'Actions', render: r => <span className="flex gap-2"><button className="text-indigo-600" onClick={() => { setEdit(r); setForm({ groupId: text(r.groupId || r.group_id), expenseName: r.expenseName || r.expense_name }) }}><Edit2 className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => remove(r)}><Trash2 className="h-4 w-4" /></button></span> }]
  return <PageFrame title="Expense Name" subtitle="Define expenses against the configured groups." busy={busy} notice={notice} setNotice={setNotice}><Card><CardHead right={<div className="flex flex-wrap gap-2"><SearchBar value={search} onChange={setSearch} /><ActionButton tone="neutral" onClick={() => downloadExcel('Expense_Name.xls', rows, [{ key: 'expenseName', label: 'Expense Name' }, { key: 'groupName', label: 'Group' }])}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton></div>}>{edit ? 'Update Expense Name' : 'Add Expense Name'}</CardHead><div className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-[1fr_1fr_auto_auto]"><Field label="Group" required><Select value={form.groupId} onChange={e => setForm(p => ({ ...p, groupId: e.target.value }))}>{groups.map(g => <option key={g.groupId || g.group_id} value={g.groupId || g.group_id}>{g.group_name || g.groupName}</option>)}</Select></Field><Field label="Expense Name" required><Input value={form.expenseName} onChange={e => setForm(p => ({ ...p, expenseName: e.target.value }))} /></Field><ActionButton onClick={save}>{edit ? 'Update' : 'Add'}</ActionButton>{edit && <ActionButton tone="neutral" onClick={() => { setEdit(null); setForm({ groupId: '', expenseName: '' }) }}>Cancel</ActionButton>}</div></Card><Card><CardHead>Expense Names</CardHead><DataTable rows={rows} columns={columns} search={search} /></Card></PageFrame>
}

function ProductGroupMaster({ boot }) {
  const [rows, setRows] = useState(boot.productGroups || []); const [name, setName] = useState(''); const [edit, setEdit] = useState(null); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  useEffect(() => setRows(boot.productGroups || []), [boot.productGroups])
  const reload = () => apiFetch('/canteen/product-groups').then(setRows)
  const save = async () => { if (!name.trim()) return show('Product group name is required', 'error'); setBusy(true); try { await apiFetch(edit ? `/canteen/product-groups/${edit.id}` : '/canteen/product-groups', { method: edit ? 'PUT' : 'POST', body: JSON.stringify({ productName: name.trim() }) }); await reload(); setName(''); setEdit(null); show('Record saved successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const remove = async row => { if (!window.confirm(`Delete ${row.productName || row.Product_name}?`)) return; setBusy(true); try { await apiFetch(`/canteen/product-groups/${row.id}`, { method: 'DELETE' }); await reload(); show('Record deleted successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Product Group', value: r => r.productName || r.Product_name }, { label: 'Actions', render: r => <span className="flex gap-2"><button className="text-indigo-600" onClick={() => { setEdit(r); setName(r.productName || r.Product_name) }}><Edit2 className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => remove(r)}><Trash2 className="h-4 w-4" /></button></span> }]
  return <PageFrame title="Product Group" subtitle="Maintain the groups used by Product Master." busy={busy} notice={notice} setNotice={setNotice}><Card><CardHead right={<div className="flex flex-wrap gap-2"><SearchBar value={search} onChange={setSearch} /><ActionButton tone="neutral" onClick={() => downloadExcel('Product_Group.xls', rows, [{ key: 'productName', label: 'Product Group' }])}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton></div>}>Product Group</CardHead><div className="grid gap-3 p-4 sm:grid-cols-[1fr_auto_auto]"><Field label="Product Group" required><Input value={name} onChange={e => setName(e.target.value)} /></Field><ActionButton onClick={save}>{edit ? 'Update' : 'Add'}</ActionButton>{edit && <ActionButton tone="neutral" onClick={() => { setEdit(null); setName('') }}>Cancel</ActionButton>}</div></Card><Card><CardHead>Product Groups</CardHead><DataTable rows={rows} columns={columns} search={search} /></Card></PageFrame>
}

function ProductMaster({ boot }) {
  const [groups, setGroups] = useState(boot.productGroups || []); const [rows, setRows] = useState([]); const [session, setSession] = useState(boot.session || ''); const [form, setForm] = useState({ productCode: '', productName: '', quantity: '', costPrice: '', sellPrice: '', addQuantity: '' }); const [edit, setEdit] = useState(null); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  useEffect(() => { setGroups(boot.productGroups || []); setSession(boot.session || ''); load(boot.session || '') }, [boot.session, boot.productGroups])
  const load = async ses => { if (!ses) return; try { setRows(await apiFetch(`/canteen/products?session=${encodeURIComponent(ses)}`)) } catch (e) { show(e.message, 'error') } }
  const clear = () => { setForm({ productCode: '', productName: '', quantity: '', costPrice: '', sellPrice: '', addQuantity: '' }); setEdit(null) }
  const save = async () => { if (!form.productCode || !form.productName.trim() || !form.costPrice || !form.sellPrice || (!edit && !form.quantity)) return show('Complete all required fields', 'error'); if (Number(form.sellPrice) < Number(form.costPrice)) return show('Sale price cannot be less than cost price', 'error'); setBusy(true); try { await apiFetch(edit ? `/canteen/products/${edit.productId}` : '/canteen/products', { method: edit ? 'PUT' : 'POST', body: JSON.stringify({ ...form, session }) }); await load(session); clear(); show(edit ? 'Record updated successfully' : 'Record saved successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const editRow = row => { setEdit(row); setForm({ productCode: text(row.productCode), productName: text(row.productName), costPrice: text(row.costPrice), sellPrice: text(row.sellPrice), quantity: '', addQuantity: '' }) }
  const remove = async row => { if (!window.confirm(`Delete ${row.productName}?`)) return; setBusy(true); try { await apiFetch(`/canteen/products/${row.productId}`, { method: 'DELETE' }); await load(session); show('Record deleted successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Product Group', value: r => r.productGroup || '' }, { label: 'Product Name', value: r => r.productName }, { label: 'Total Qty', value: r => r.totalQty }, { label: 'Issue Qty', value: r => r.issueQty }, { label: 'Remaining Qty', value: r => r.remQty }, { label: 'Cost Price', value: r => r.costPrice }, { label: 'Sale Price', value: r => r.sellPrice }, { label: 'Actions', render: r => <span className="flex gap-2"><button className="text-indigo-600" onClick={() => editRow(r)}><Edit2 className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => remove(r)}><Trash2 className="h-4 w-4" /></button></span> }]
  return <PageFrame title="Product Master" subtitle="Add stock, update quantity and maintain product prices." busy={busy} notice={notice} setNotice={setNotice}><Card><CardHead right={<div className="flex flex-wrap gap-2"><SearchBar value={search} onChange={setSearch} /><ActionButton tone="neutral" onClick={() => downloadExcel(`Product_Report_${session}.xls`, rows, [{ key: 'productGroup', label: 'Product Group' }, { key: 'productName', label: 'Product Name' }, { key: 'totalQty', label: 'Total Qty' }, { key: 'issueQty', label: 'Issue Qty' }, { key: 'remQty', label: 'Remaining Qty' }])}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton></div>}>{edit ? 'Update Product Detail' : 'Add Product Detail'}</CardHead><div className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Product Group" required><Select value={form.productCode} onChange={e => setForm(p => ({ ...p, productCode: e.target.value }))}>{groups.map(g => <option key={g.productCode || g.Product_code || g.id} value={g.productCode || g.Product_code || ''}>{g.productName || g.Product_name}</option>)}</Select></Field><Field label="Product Name" required><Input value={form.productName} onChange={e => setForm(p => ({ ...p, productName: e.target.value }))} /></Field><Field label="Max Quantity" required={!edit}><Input type="number" value={form.quantity} disabled={!!edit} onChange={e => setForm(p => ({ ...p, quantity: e.target.value }))} /></Field><Field label="Add Quantity"><Input type="number" value={form.addQuantity} disabled={!edit} onChange={e => setForm(p => ({ ...p, addQuantity: e.target.value }))} /></Field><Field label="Cost Price" required><Input type="number" value={form.costPrice} onChange={e => setForm(p => ({ ...p, costPrice: e.target.value }))} /></Field><Field label="Sale Price" required><Input type="number" value={form.sellPrice} onChange={e => setForm(p => ({ ...p, sellPrice: e.target.value }))} /></Field><div className="flex items-end gap-2"><ActionButton onClick={save}>{edit ? 'Update' : 'Add'}</ActionButton>{edit && <ActionButton tone="neutral" onClick={clear}>Clear</ActionButton>}</div></div></Card><Card><CardHead>Product Details <span className="ml-2 text-xs font-normal text-slate-400">Session: {session}</span></CardHead><DataTable rows={rows} columns={columns} search={search} /></Card></PageFrame>
}

function CreditBalance({ boot }) {
  const [session, setSession] = useState(boot.session || ''); const [rows, setRows] = useState([]); const [search, setSearch] = useState(''); const [edit, setEdit] = useState(null); const [value, setValue] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  const load = async ses => { if (ses) { setBusy(true); try { setRows(await apiFetch(`/canteen/credit-balances?session=${encodeURIComponent(ses)}`)) } catch (e) { show(e.message, 'error') } finally { setBusy(false) } } }
  useEffect(() => { setSession(boot.session || ''); load(boot.session || '') }, [boot.session])
  const save = async row => { setBusy(true); try { await apiFetch(`/canteen/credit-balances/${encodeURIComponent(row.registrationNo)}`, { method: 'PUT', body: JSON.stringify({ session, creditBalance: value }) }); setEdit(null); setRows(await apiFetch(`/canteen/credit-balances?session=${encodeURIComponent(session)}`)); show('Record Updated Sucessfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Registration No.', value: r => r.registrationNo }, { label: 'Name', value: r => r.name }, { label: 'Class', value: r => r.className }, { label: 'Credit Balance', render: r => edit === r.registrationNo ? <div className="flex gap-2"><Input type="number" value={value} onChange={e => setValue(e.target.value)} /><button className="text-emerald-600" onClick={() => save(r)}><Check className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => setEdit(null)}><X className="h-4 w-4" /></button></div> : <button className="font-semibold text-indigo-600" onClick={() => { setEdit(r.registrationNo); setValue(text(r.creditBalance)) }}>{num(r.creditBalance)}</button> }]
  return <PageFrame title="Update Credit Balance" subtitle="Update the credit balance for students in the selected session." busy={busy} notice={notice} setNotice={setNotice}><Card><div className="grid gap-3 p-4 sm:grid-cols-[minmax(220px,360px)_1fr_auto]"><Field label="Session" required><Select value={session} onChange={e => { setSession(e.target.value); load(e.target.value) }}>{(boot.sessions || []).map(s => <option key={s.value} value={s.value}>{s.label}</option>)}</Select></Field><div className="flex items-end"><SearchBar value={search} onChange={setSearch} /></div><div className="flex items-end gap-2"><ActionButton tone="neutral" onClick={() => downloadExcel(`update-credit-balance-${session}.xls`, rows, [{ key: 'registrationNo', label: 'Registration No.' }, { key: 'name', label: 'Name' }, { key: 'className', label: 'Class' }, { key: 'creditBalance', label: 'Credit Balance' }])}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton><ActionButton tone="neutral" onClick={() => load(session)}><RefreshCw className="h-4 w-4" /> Show</ActionButton></div></div></Card><Card><CardHead>Credit Balance</CardHead><DataTable rows={rows} columns={columns} search={search} /></Card></PageFrame>
}

function AssignExpense({ boot }) {
  const [session, setSession] = useState(boot.session || ''); const [secId, setSecId] = useState(''); const [studentId, setStudentId] = useState(''); const [registrationNo, setRegistrationNo] = useState(''); const [students, setStudents] = useState([]); const [student, setStudent] = useState(null); const [rows, setRows] = useState([{ rowId: 1, expenseCode: '', amount: '', description: '' }]); const [history, setHistory] = useState({ rows: [], summary: [] }); const [historyOpen, setHistoryOpen] = useState(false); const [historyEdit, setHistoryEdit] = useState(null); const [date, setDate] = useState(today()); const [searchSuggestions, setSearchSuggestions] = useState([]); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  const classes = boot.classes || []; const expenses = boot.expenseNames || []
  useEffect(() => { setSession(boot.session || '') }, [boot.session])
  useEffect(() => { if (!session || !secId) { setStudents([]); return } apiFetch(`/canteen/students?session=${encodeURIComponent(session)}&secId=${encodeURIComponent(secId)}`).then(setStudents).catch(e => { setStudents([]); show(e.message, 'error') }) }, [session, secId])
  const loadStudent = async reg => { if (!reg || !session) return; setBusy(true); try { const found = await apiFetch(`/canteen/student?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(reg)}`); setStudent(found); setRegistrationNo(found.registrationNo); setStudentId(text(found.studentId)); setSecId(text(found.secId)); const list = await apiFetch(`/canteen/expense-history?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(found.registrationNo)}`); setHistory(list) } catch (e) { setStudent(null); show(e.message, 'error') } finally { setBusy(false) } }
  const changeStudent = id => { setStudentId(id); const found = students.find(s => text(s.studentId) === text(id)); if (found) loadStudent(found.registrationNo) }
  const addRow = () => setRows(p => [...p, { rowId: Date.now(), expenseCode: '', amount: '', description: '' }])
  const save = async () => { if (!student) return show('Select a student first', 'error'); const valid = rows.filter(r => r.expenseCode && Number(r.amount) > 0); if (!valid.length) return show('Select an expense and enter amount', 'error'); setBusy(true); try { await apiFetch('/canteen/assign-expenses', { method: 'POST', body: JSON.stringify({ session, registrationNo: student.registrationNo, transDate: date, rows: valid }) }); const fresh = await apiFetch(`/canteen/student?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`); setStudent(fresh); setRows([{ rowId: Date.now(), expenseCode: '', amount: '', description: '' }]); show('Record Saved Successfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const openHistory = async () => { if (!student) return show('Select a student first', 'error'); setBusy(true); try { setHistory(await apiFetch(`/canteen/expense-history?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`)); setHistoryOpen(true) } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const editHistorySave = async () => { if (!historyEdit) return; setBusy(true); try { await apiFetch(`/canteen/assign-expenses/${historyEdit.id}?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`, { method: 'PUT', body: JSON.stringify(historyEdit) }); setHistory(await apiFetch(`/canteen/expense-history?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`)); setHistoryEdit(null); show('Record Updated Sucessfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const removeHistory = async row => { if (!window.confirm('Delete this expense?')) return; setBusy(true); try { await apiFetch(`/canteen/assign-expenses/${row.id}?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`, { method: 'DELETE' }); setHistory(await apiFetch(`/canteen/expense-history?session=${encodeURIComponent(session)}&registrationNo=${encodeURIComponent(student.registrationNo)}`)); show('Record Deleted Sucessfully') } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const searchReg = async value => { setRegistrationNo(value); if (value.length < 1) return setSearchSuggestions([]); try { setSearchSuggestions(await apiFetch(`/canteen/registration-suggestions?session=${encodeURIComponent(session)}&prefix=${encodeURIComponent(value)}`)) } catch { setSearchSuggestions([]) } }
  const columns = [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'I No.', value: r => r.registrationNo }, { label: 'Expense Name', value: r => r.expenseName }, { label: 'Transaction Date', value: r => r.transDate }, { label: 'Charge', value: r => num(r.charges) }, { label: 'Class', value: r => r.className }, { label: 'Description', value: r => r.description }, { label: 'Actions', render: r => <span className="flex gap-2"><button className="text-indigo-600" onClick={() => setHistoryEdit({ ...r, expenseCode: r.expenseCode, transDate: r.transDate, charges: r.charges })}><Edit2 className="h-4 w-4" /></button><button className="text-rose-600" onClick={() => removeHistory(r)}><Trash2 className="h-4 w-4" /></button></span> }]
  return <PageFrame title="Assign Expense" subtitle="Assign one or more Canteen expenses to a student and view the same transaction history as the legacy page." busy={busy} notice={notice} setNotice={setNotice}><Card><CardHead right={<ActionButton tone="neutral" onClick={() => { setStudent(null); setRegistrationNo(''); setStudentId(''); setSecId(''); setStudents([]); setRows([{ rowId: Date.now(), expenseCode: '', amount: '', description: '' }]) }}><RefreshCw className="h-4 w-4" /> Reset</ActionButton>}>Find Student</CardHead><div className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Session" required><Select value={session} onChange={e => { setSession(e.target.value); setStudent(null); setSecId(''); setStudentId(''); setStudents([]) }}>{(boot.sessions || []).map(s => <option key={s.value} value={s.value}>{s.label}</option>)}</Select></Field><Field label="Class"><Select value={secId} onChange={e => { setSecId(e.target.value); setStudentId(''); setStudent(null) }}><>{classes.map(c => <option key={c.secId} value={c.secId}>{c.className} ({c.section})</option>)}</></Select></Field><Field label="Student"><Select value={studentId} onChange={e => changeStudent(e.target.value)} disabled={!secId}>{students.map(s => <option key={s.studentId} value={s.studentId}>{s.nameWithFather || s.name}</option>)}</Select></Field><Field label="Registration No."><div className="relative"><Input value={registrationNo} onChange={e => searchReg(e.target.value)} onBlur={() => setTimeout(() => setSearchSuggestions([]), 150)} placeholder="Type registration no." />{searchSuggestions.length > 0 && <div className="absolute z-20 mt-1 max-h-40 w-full overflow-auto rounded-lg border bg-white shadow-lg dark:border-indigo-500/20 dark:bg-[#1e2238]">{searchSuggestions.map(s => <button key={s.registrationNo} className="block w-full px-3 py-2 text-left text-sm hover:bg-indigo-50 dark:hover:bg-indigo-500/10" onMouseDown={() => { setSearchSuggestions([]); loadStudent(s.registrationNo) }}>{s.registrationNo}</button>)}</div>}</div></Field></div></Card>{student && <><Card><div className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-5"><div><small className="text-xs text-slate-500">Student</small><p className="font-semibold dark:text-slate-100">{student.name}</p></div><div><small className="text-xs text-slate-500">Father Name</small><p className="font-semibold dark:text-slate-100">{student.fatherName}</p></div><div><small className="text-xs text-slate-500">Class</small><p className="font-semibold dark:text-slate-100">{student.className} ({student.section})</p></div><div><small className="text-xs text-slate-500">Debit Balance</small><p className="font-semibold text-rose-600">₹{num(student.debitBalance)}</p></div><div><small className="text-xs text-slate-500">Credit Balance</small><p className="font-semibold text-emerald-600">₹{num(student.creditBalance)}</p></div></div></Card><Card><CardHead right={<div className="flex flex-wrap gap-2"><ActionButton tone="neutral" onClick={openHistory}><Eye className="h-4 w-4" /> Debit Balance</ActionButton><ActionButton onClick={addRow}><Plus className="h-4 w-4" /> Add</ActionButton></div>}>Expense Entries</CardHead><div className="space-y-3 p-4">{rows.map((row, i) => <div key={row.rowId} className="grid gap-2 rounded-xl border border-slate-100 p-3 dark:border-white/5 sm:grid-cols-[1fr_160px_1fr_auto]"><Field label={`Select Expense ${i + 1}`}><Select value={row.expenseCode} onChange={e => setRows(p => p.map(x => x.rowId === row.rowId ? { ...x, expenseCode: e.target.value } : x))}>{expenses.map(e => <option key={e.expenseCode || e.expense_code} value={e.expenseCode || e.expense_code}>{e.expenseName || e.expense_name}</option>)}</Select></Field><Field label="Amount"><Input type="number" value={row.amount} onChange={e => setRows(p => p.map(x => x.rowId === row.rowId ? { ...x, amount: e.target.value } : x))} /></Field><Field label="Description"><Input value={row.description} onChange={e => setRows(p => p.map(x => x.rowId === row.rowId ? { ...x, description: e.target.value } : x))} /></Field><button className="self-end rounded-lg p-2 text-rose-600 disabled:opacity-30" disabled={rows.length === 1} onClick={() => setRows(p => p.filter(x => x.rowId !== row.rowId))}><Trash2 className="h-4 w-4" /></button></div>)}<div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-end"><Field label="Transaction Date"><Input type="date" value={date} onChange={e => setDate(e.target.value)} /></Field><ActionButton onClick={save}><Check className="h-4 w-4" /> Save</ActionButton></div></div></Card></>}{historyOpen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-3"><div className="max-h-[90vh] w-full max-w-6xl overflow-auto rounded-2xl bg-white p-4 dark:bg-[#15182a]"><div className="mb-3 flex items-center justify-between"><h2 className="font-bold dark:text-slate-100">Expense History</h2><button onClick={() => setHistoryOpen(false)}><X /></button></div>{historyEdit && <div className="mb-3 grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-4 dark:bg-white/[.03]"><Field label="Expense"><Select value={historyEdit.expenseCode} onChange={e => setHistoryEdit(p => ({ ...p, expenseCode: e.target.value }))}>{expenses.map(e => <option key={e.expenseCode} value={e.expenseCode}>{e.expenseName}</option>)}</Select></Field><Field label="Date"><Input value={historyEdit.transDate} onChange={e => setHistoryEdit(p => ({ ...p, transDate: e.target.value }))} /></Field><Field label="Charge"><Input type="number" value={historyEdit.charges} onChange={e => setHistoryEdit(p => ({ ...p, charges: e.target.value }))} /></Field><div className="flex items-end gap-2"><ActionButton onClick={editHistorySave}>Save</ActionButton><ActionButton tone="neutral" onClick={() => setHistoryEdit(null)}>Cancel</ActionButton></div></div>}<DataTable rows={history.rows || []} columns={columns} /></div></div>}</PageFrame>
}

function ReportFilters({ boot, filters, setFilters, onShow, onReset, includeClass = false, includeStudent = false, children }) {
  const classes = boot.classes || []; const classOptions = Array.from(new Map(classes.map(c => [c.classId, c])).values()); const sections = classes.filter(c => text(c.classId) === text(filters.classId)); const [students, setStudents] = useState([])
  useEffect(() => { if (filters.session && filters.secId) apiFetch(`/canteen/students?session=${encodeURIComponent(filters.session)}&secId=${filters.secId}`).then(setStudents).catch(() => setStudents([])); else setStudents([]) }, [filters.session, filters.secId])
  return <Card><div className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4"> <Field label="Session" required><Select value={filters.session} onChange={e => setFilters(p => ({ ...p, session: e.target.value, classId: '', secId: '', studentId: '' }))}>{(boot.sessions || []).map(s => <option key={s.value} value={s.value}>{s.label}</option>)}</Select></Field>{includeClass && <Field label="Class"><Select value={filters.classId} onChange={e => setFilters(p => ({ ...p, classId: e.target.value, secId: '', studentId: '' }))}>{classOptions.map(c => <option key={c.classId} value={c.classId}>{c.className}</option>)}</Select></Field>}{includeClass && <Field label="Section"><Select value={filters.secId} onChange={e => setFilters(p => ({ ...p, secId: e.target.value, studentId: '' }))} disabled={!filters.classId}>{sections.map(c => <option key={c.secId} value={c.secId}>{c.section}</option>)}</Select></Field>}{includeStudent && <Field label="Student"><Select value={filters.studentId} onChange={e => setFilters(p => ({ ...p, studentId: e.target.value }))} disabled={!filters.secId}>{students.map(s => <option key={s.registrationNo} value={s.registrationNo}>{s.nameWithFather || s.name}</option>)}</Select></Field>}{children}<div className="flex items-end gap-2"><ActionButton onClick={onShow}><Eye className="h-4 w-4" /> Show</ActionButton><ActionButton tone="neutral" onClick={onReset}><RefreshCw className="h-4 w-4" /> Reset</ActionButton></div></div></Card>
}

const reportColumns = kind => ({
  debitCredit: [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'ID No', key: 'idNo' }, { label: 'Student Name', key: 'studentName' }, { label: 'Class', key: 'className' }, { label: 'Credit Balance', value: r => num(r.creditBalance) }, { label: 'Debit Balance', value: r => num(r.debitBalance) }, { label: 'Balance', key: 'balance' }],
  productBalance: [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Product Name', key: 'productName' }, { label: 'Total Qty', key: 'totalQty' }, { label: 'Cost Price', value: r => num(r.costPrice) }, { label: 'Total C.P', value: r => num(r.totalCp) }, { label: 'Issue Qty', key: 'issueQty' }, { label: 'Sell Price', value: r => num(r.sp) }, { label: 'Total S.P', value: r => num(r.totalSp) }, { label: 'Remaining Qty', key: 'remQty' }, { label: 'Total Amt.', value: r => num(r.totalAmt) }],
  remaining: [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Product Group', key: 'productGroup' }, { label: 'Product Name', key: 'productName' }, { label: 'Total Qty', key: 'totalQty' }, { label: 'Issue Qty', key: 'issueQty' }, { label: 'Remaining Qty', key: 'remQty' }, { label: 'Add Qty', key: 'addQty' }],
  assignReport: [{ label: 'S.No', key: 'sno' }, { label: 'Registration No.', key: 'registrationNo' }, { label: 'Name', key: 'name' }, { label: 'Total Expense', value: r => num(r.charges) }],
  issues: [{ label: 'Registration No', key: 'registrationNo' }, { label: 'Req No.', key: 'reqNo' }, { label: 'Date', key: 'transDate' }, { label: 'Product Name', key: 'productName' }, { label: 'Quantity', key: 'quantity' }, { label: 'Price', value: r => num(r.price) }, { label: 'Total Price', value: r => num(r.totalPrice) }, { label: 'User', key: 'userType' }],
  productReport: [{ label: 'S.No', value: (_, i) => i + 1 }, { label: 'Account Type', key: 'userType' }, { label: 'Quantity', key: 'quantity' }, { label: 'Total Price', value: r => num(r.total) }],
})

function Invoice({ invoice, onPrint }) {
  if (!invoice) return <Empty text="Select session, class, section and student, then press Show." />
  const school = invoice.school?.[0] || {}; const student = invoice.student || {}; const feeRows = invoice.feeCharges || []; const creditRows = invoice.credit || []; const expenseRows = invoice.expenses || []; const summaryRows = invoice.summary || []; const installmentRows = invoice.installment || []
  const money = value => `${String.fromCharCode(0x20B9)}${num(value)}`
  const amount = value => value == null || value === '' ? '' : typeof value === 'string' && /^[+-]\s/.test(value) ? `${String.fromCharCode(0x20B9)}${value}` : money(value)
  const bankRows = [{ name: school.bankName, account: school.bankAccount, branch: school.bankBranch, ifsc: school.ifsc }, { name: school.bankNameNew, account: school.bankAccountNew, branch: '', ifsc: school.ifscNew }].filter(row => row.name || row.account || row.ifsc)
  return <Card className="mx-auto max-w-5xl overflow-hidden"><div className="border-b p-5 text-center dark:border-white/5"><h2 className="text-lg font-bold dark:text-slate-100">{school.schoolname || 'School'}</h2><p className="text-sm text-slate-500 dark:text-slate-400">{school.address || ''}</p><p className="mt-2 text-sm font-bold dark:text-slate-200">FEE DEPOSIT ORDER CUM PERSONAL ACCOUNT</p><p className="text-xs text-slate-500">(FROM APRIL {invoice.fromSession || ''} TO MARCH {invoice.toSession || ''})</p></div><div className="grid gap-3 border-b p-5 text-sm dark:border-white/5 sm:grid-cols-2 lg:grid-cols-4"><p><span className="text-slate-500">ID NO:</span> <b>{student.registrationNo || ''}</b></p><p><span className="text-slate-500">Name:</span> <b>{student.name || ''}</b></p><p><span className="text-slate-500">Father Name:</span> <b>{student.fatherName || ''}</b></p><p><span className="text-slate-500">Class:</span> <b>{student.promotedClassName || student.className || ''}{student.section ? ` (${student.section})` : ''}</b></p></div><div className="grid gap-5 p-5 lg:grid-cols-2"><section><h3 className="mb-2 text-sm font-bold dark:text-slate-100">Fee Details</h3><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-left">S.No</th><th className="px-2 py-2 text-left">Fee Head</th><th className="px-2 py-2 text-right">Fee Charge</th></tr></thead><tbody>{feeRows.map((row, index) => <tr key={`fee-${index}`} className={`border-b dark:border-white/5 ${String(row.feeHead).toUpperCase() === 'TOTAL' ? 'font-bold' : ''}`}><td className="px-2 py-2">{String(row.feeHead).toUpperCase() === 'TOTAL' ? '' : row.sno || index + 1}</td><td className="px-2 py-2">{row.feeHead || ''}</td><td className="px-2 py-2 text-right">{row.feeCharge == null ? '' : money(row.feeCharge)}</td></tr>)}</tbody></table></div></section><section><h3 className="mb-2 text-sm font-bold dark:text-slate-100">Credits in PDA</h3><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-left">Session</th><th className="px-2 py-2 text-right">Credit Balance</th></tr></thead><tbody>{creditRows.length ? creditRows.map((row, index) => <tr key={`credit-${index}`} className="border-b dark:border-white/5"><td className="px-2 py-2">{row.session || invoice.session || ''}</td><td className="px-2 py-2 text-right">{money(row.creditBalance)}</td></tr>) : <tr><td className="px-2 py-2" colSpan="2"></td></tr>}</tbody></table></div><h3 className="mb-2 mt-5 text-sm font-bold dark:text-slate-100">Details of PDA Expenses</h3><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-left">S.No</th><th className="px-2 py-2 text-left">Expense Name</th><th className="px-2 py-2 text-right">Total Expense</th></tr></thead><tbody>{expenseRows.map((row, index) => <tr key={`expense-${index}`} className={`border-b dark:border-white/5 ${String(row.expenseName).toUpperCase() === 'TOTAL' ? 'font-bold' : ''}`}><td className="px-2 py-2">{String(row.expenseName).toUpperCase() === 'TOTAL' ? '' : row.sno || index + 1}</td><td className="px-2 py-2">{row.expenseName || ''}</td><td className="px-2 py-2 text-right">{row.charges == null ? '' : money(row.charges)}</td></tr>)}</tbody></table></div></section></div><div className="grid gap-5 border-t p-5 dark:border-white/5 lg:grid-cols-2"><section><h3 className="mb-2 text-sm font-bold dark:text-slate-100">Amount Summary</h3><table className="min-w-full text-sm"><tbody>{summaryRows.map((row, index) => <tr key={`summary-${index}`} className="border-b dark:border-white/5"><td className="px-2 py-2">{row.total || ''}</td><td className="px-2 py-2 text-right font-semibold">{amount(row.totalFee ?? row.total_fee)}</td></tr>)}</tbody></table></section><section><h3 className="mb-2 text-sm font-bold dark:text-slate-100">Installment Details</h3>{installmentRows.length ? <table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-right">Installment 1</th><th className="px-2 py-2 text-right">Installment 2</th><th className="px-2 py-2 text-left">To Session</th></tr></thead><tbody>{installmentRows.map((row, index) => <tr key={`inst-${index}`}><td className="px-2 py-2 text-right">{money(row.inst1)}</td><td className="px-2 py-2 text-right">{money(row.inst2)}</td><td className="px-2 py-2">{row.toSession || ''}</td></tr>)}</tbody></table> : <p className="text-sm text-slate-500">No installment record found.</p>}</section></div>{bankRows.length > 0 && <section className="border-t p-5 dark:border-white/5"><h3 className="mb-2 text-sm font-bold dark:text-slate-100">Bank / Payment Details</h3><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-left">Bank</th><th className="px-2 py-2 text-left">Account No.</th><th className="px-2 py-2 text-left">Branch</th><th className="px-2 py-2 text-left">IFSC</th></tr></thead><tbody>{bankRows.map((row, index) => <tr key={`bank-${index}`} className="border-b dark:border-white/5"><td className="px-2 py-2">{row.name || ''}</td><td className="px-2 py-2">{row.account || ''}</td><td className="px-2 py-2">{row.branch || ''}</td><td className="px-2 py-2">{row.ifsc || ''}</td></tr>)}</tbody></table>{(school.mobile || school.mobile1) && <p className="mt-2 text-xs text-slate-500">Contact: {school.mobile || school.mobile1}</p>}</div></section>}<div className="flex items-end justify-between gap-3 p-5"><div>{school.principalSignature && <img src={school.principalSignature} alt="Principal signature" className="h-14 max-w-32 object-contain" />}<p className="text-xs font-semibold dark:text-slate-200">Principal</p></div><ActionButton tone="neutral" onClick={onPrint}>Print</ActionButton></div></Card>
}

function InvoiceLegacy({ invoice, onPrint }) {
  if (!invoice) return <Empty text="Select session, class, section and student, then press Show." />
  const school = invoice.school?.[0] || {}; const student = invoice.student || {}; const expenses = invoice.expenses || []; return <Card className="mx-auto max-w-4xl"><div className="border-b p-5 text-center dark:border-white/5"><h2 className="text-lg font-bold dark:text-slate-100">{school.schoolname || 'School'}</h2><p className="text-sm text-slate-500">{school.address || ''}</p><p className="mt-2 text-sm font-semibold dark:text-slate-200">Canteen Invoice</p></div><div className="grid gap-3 p-5 text-sm sm:grid-cols-3"><p><span className="text-slate-500">Student:</span> <b>{student.name}</b></p><p><span className="text-slate-500">Registration No:</span> <b>{student.registrationNo}</b></p><p><span className="text-slate-500">Class:</span> <b>{student.className} ({student.section})</b></p></div><div className="overflow-x-auto px-5"><table className="min-w-full text-sm"><thead><tr className="border-b dark:border-white/10"><th className="px-2 py-2 text-left">Expense / Fee Head</th><th className="px-2 py-2 text-right">Amount</th></tr></thead><tbody>{(invoice.feeCharges || []).map((r, i) => <tr key={i} className="border-b dark:border-white/5"><td className="px-2 py-2">{r.feeHead}</td><td className="px-2 py-2 text-right">₹{num(r.feeCharge)}</td></tr>)}{expenses.map((r, i) => <tr key={`e${i}`} className="border-b dark:border-white/5"><td className="px-2 py-2">{r.expenseName}</td><td className="px-2 py-2 text-right">₹{num(r.charges)}</td></tr>)}</tbody></table></div><div className="flex justify-end gap-2 p-5"><ActionButton tone="neutral" onClick={onPrint}>Print</ActionButton></div></Card>
}

function Reports({ boot, kind }) {
  const [filters, setFilters] = useState({ session: boot.session || '', classId: '', secId: '', studentId: '', userType: kind === 'issues' ? '0' : '0', registrationNo: '' }); const [rows, setRows] = useState([]); const [invoice, setInvoice] = useState(null); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice, show] = useNotice()
  useEffect(() => setFilters(p => ({ ...p, session: boot.session || p.session })), [boot.session])
  const load = async () => { if (!filters.session) return show('Select session', 'error'); if (kind === 'invoice' && !filters.studentId) return show('Select student', 'error'); setBusy(true); try { let data; if (kind === 'debitCredit') data = (await apiFetch(`/canteen/reports/debit-credit?session=${encodeURIComponent(filters.session)}&classId=${filters.classId || 0}&secId=${filters.secId || 0}`)).rows; if (kind === 'invoice') { const reg = filters.studentId; data = null; setInvoice(await apiFetch(`/canteen/reports/invoice?session=${encodeURIComponent(filters.session)}&registrationNo=${encodeURIComponent(reg)}&classId=${filters.classId || 0}&secId=${filters.secId || 0}`)) } if (kind === 'productBalance') data = await apiFetch(`/canteen/reports/product-balance?session=${encodeURIComponent(filters.session)}`); if (kind === 'remaining') data = await apiFetch(`/canteen/reports/remaining-products?session=${encodeURIComponent(filters.session)}`); if (kind === 'assignReport') data = await apiFetch(`/canteen/reports/assign-expenses?session=${encodeURIComponent(filters.session)}`); if (kind === 'issues') data = await apiFetch(`/canteen/reports/product-issues?session=${encodeURIComponent(filters.session)}&userType=${filters.userType}&registrationNo=${encodeURIComponent(filters.registrationNo)}`); if (kind === 'productReport') data = await apiFetch(`/canteen/reports/product-report?session=${encodeURIComponent(filters.session)}&userType=${filters.userType}`); if (data) setRows(data); show(kind === 'invoice' ? 'Invoice loaded' : `${data?.length || 0} record(s) loaded`) } catch (e) { show(e.message, 'error') } finally { setBusy(false) } }
  const reset = () => { setRows([]); setInvoice(null); setSearch(''); setFilters(p => ({ ...p, session: boot.session || '', classId: '', secId: '', studentId: '', userType: '0', registrationNo: '' })) }
  useEffect(() => { if (['productBalance', 'remaining', 'assignReport'].includes(kind) && boot.session) load() }, [boot.session, kind])
  const title = { debitCredit: 'Debit Credit Balance Report', invoice: 'Print Invoice', productBalance: 'Product Balance Report', remaining: 'Remaining Product Report', assignReport: 'Assign Expense Report', issues: 'Product Issue Detail', productReport: 'Canteen Product Report' }[kind]
  const columns = reportColumns(kind); const filename = `${title.replaceAll(' ', '_')}.xls`; const exportRows = rows.length ? rows : []
  const print = () => { const w = window.open('', '_blank'); if (!w) return; const source = document.querySelector('[data-canteen-invoice]'); const printable = source?.cloneNode(true); printable?.querySelectorAll('button').forEach(button => button.remove()); const styles = Array.from(document.querySelectorAll('link[rel="stylesheet"],style')).map(node => node.outerHTML).join(''); w.document.write(`<html><head><title>${title}</title>${styles}<style>@media print{body{background:#fff!important}.shadow-sm{box-shadow:none!important}.no-print{display:none!important}}</style></head><body>${printable?.outerHTML || ''}</body></html>`); w.document.close(); w.focus(); w.print() }
  return <PageFrame title={title} subtitle="The report uses the same session, class, section and transaction tables as the legacy page." busy={busy} notice={notice} setNotice={setNotice}><ReportFilters boot={boot} filters={filters} setFilters={setFilters} onShow={load} onReset={reset} includeClass={kind === 'debitCredit' || kind === 'invoice'} includeStudent={kind === 'invoice'}>{(kind === 'issues' || kind === 'productReport') && <Field label="User Type"><Select value={filters.userType} onChange={e => setFilters(p => ({ ...p, userType: e.target.value }))}><option value="0">-- Select All --</option>{kind === 'issues' ? <><option value="S">Student</option><option value="ST">Staff</option><option value="F">Office</option></> : <><option value="1">Student</option><option value="3">Staff</option><option value="2">Office</option></>}</Select></Field>}{kind === 'issues' && <Field label="Admission No."><Input value={filters.registrationNo} onChange={e => setFilters(p => ({ ...p, registrationNo: e.target.value }))} /></Field>}</ReportFilters>{kind === 'invoice' ? <div data-canteen-invoice><Invoice invoice={invoice} onPrint={print} /></div> : <Card><CardHead right={<div className="flex flex-wrap gap-2"><SearchBar value={search} onChange={setSearch} /> <ActionButton tone="neutral" onClick={() => downloadExcel(filename, exportRows, columns.filter(c => c.key || c.label).map(c => ({ key: c.key, label: c.label, value: c.value })))} disabled={!rows.length}><FileSpreadsheet className="h-4 w-4" /> Excel</ActionButton></div>}>Report Data</CardHead><div className="p-3"><DataTable rows={rows} columns={columns} search={search} /></div></Card>}</PageFrame>
}

export default function CanteenModulePage({ mode }) {
  const [boot, setBoot] = useState(null); const [error, setError] = useState('');
  useEffect(() => { apiFetch('/canteen/bootstrap').then(setBoot).catch(e => setError(e.message)) }, [])
  if (error) return <div className="rounded-xl border border-rose-200 bg-rose-50 p-5 text-rose-700">{error}</div>
  if (!boot) return <div className="flex min-h-48 items-center justify-center text-slate-500"><Loader2 className="mr-2 h-5 w-5 animate-spin" /> Loading Canteen…</div>
  if (mode === 'groups') return <GroupMaster boot={boot} />
  if (mode === 'names') return <ExpenseNameMaster boot={boot} />
  if (mode === 'productGroups') return <ProductGroupMaster boot={boot} />
  if (mode === 'products') return <ProductMaster boot={boot} />
  if (mode === 'credits') return <CreditBalance boot={boot} />
  if (mode === 'assign') return <AssignExpense boot={boot} />
  return <Reports boot={boot} kind={mode} />
}
